<?php /** @var array<string,mixed> $e */ /** @var array<string,mixed> $d */ /** @var array<string,mixed> $formula */ /** @var bool $canApprove */ /** @var bool $canAdjust */ use Vertex\Core\View;
$url = '/commissions/' . $e['public_id']; $st = $e['status']; ?>
<div class="page-head"><div><p class="eyebrow">Commission entry</p><h1><?= e($e['reference']) ?></h1></div><a class="btn btn-ghost" href="/commissions">&larr; Ledger</a></div>
<div class="panel"><div class="detail-grid"><div><span class="muted">Status</span><br><?= View::partial('pbadge', ['kind' => 'commission', 's' => $st]) ?></div><div><span class="muted">Milestone</span><br><?= e(config("referrals.milestone_labels.{$e['milestone']}", $e['milestone'])) ?></div>
    <div><span class="muted">Rate</span><br><?= e(rtrim(rtrim(number_format((int) $e['rate_bps'] / 100, 2), '0'), '.')) ?>%</div><div><span class="muted">Base</span><br><?= e(money($e['base_minor'])) ?></div>
    <div><span class="muted">Amount</span><br><strong><?= e(money($e['amount_minor'])) ?></strong></div><div><span class="muted">Rules version</span><br><?= $e['rules_version'] === null ? '—' : ((int) $e['rules_version'] === 0 ? 'defaults' : 'v' . (int) $e['rules_version']) ?></div></div>
    <dl class="detail-list"><dt>Partner</dt><dd><?= e($e['partner_name'] ?? '') ?></dd><dt>Referral</dt><dd><a href="/referrals/<?= e($e['referral_public_id'] ?? '') ?>"><?= e($e['referral_reference'] ?? '') ?></a></dd>
        <?php if (!empty($e['project_code'])) : ?><dt>Project</dt><dd><?= e($e['project_code']) ?></dd><?php endif; ?>
        <?php if ($e['reason']) : ?><dt>Reason</dt><dd class="prewrap"><?= e($e['reason']) ?></dd><?php endif; ?><?php if ($e['partner_note']) : ?><dt>Shown to the partner</dt><dd><?= e($e['partner_note']) ?></dd><?php endif; ?>
        <?php if ($e['approved_at']) : ?><dt>Approved</dt><dd><?= e(local_time($e['approved_at'])) ?></dd><?php endif; ?><?php if ($e['payable_after']) : ?><dt>Payable after</dt><dd><?= e(local_date($e['payable_after'])) ?></dd><?php endif; ?></dl></div>
<div class="panel"><h2>How this was calculated</h2><p class="muted">The inputs and formula stored with the entry when it was calculated. They do not change when the rules change.</p>
    <dl class="detail-list"><?php $fmt = static function (string $k, mixed $val): string { if (is_array($val)) { $out = []; foreach ($val as $kk => $vv) { $out[] = preg_replace('/ minor$/', '', str_replace('_', ' ', (string) $kk)) . ': ' . (is_array($vv) ? json_encode($vv) : (is_bool($vv) ? ($vv ? 'yes' : 'no') : (str_ends_with((string) $kk, '_minor') && is_int($vv) ? money($vv) : (string) $vv))); } return implode('; ', $out); } return is_bool($val) ? ($val ? 'yes' : 'no') : (str_ends_with($k, '_minor') && is_int($val) ? money($val) : (string) $val); };
    foreach ($formula as $k => $val) : ?><dt><?= e(preg_replace('/ minor$/', '', str_replace('_', ' ', (string) $k))) ?></dt><dd><?= e($fmt((string) $k, $val)) ?></dd><?php endforeach; ?></dl>
    <?php if ($d['payments'] !== []) : ?><h3>Payments counted</h3><div class="table-wrap"><table class="table"><thead><tr><th>Payment</th><th>Invoice</th><th>Role</th><th class="num">Gross</th><th class="num">Refunded</th><th class="num">Counted</th><th>Status</th></tr></thead><tbody>
        <?php foreach ($d['payments'] as $p) : ?><tr><td><a href="/client-payments/<?= e($p['public_id']) ?>"><?= e($p['reference']) ?></a></td><td><?= e($p['invoice_ref'] ?? '—') ?></td><td><?= e(ucfirst($p['payment_role'])) ?></td><td class="num"><?= e(money($p['gross_minor'])) ?></td><td class="num"><?= e(money($p['refunded_minor'])) ?></td><td class="num"><?= e(money($p['eligible_minor'])) ?></td><td><?= View::partial('pbadge', ['kind' => 'payment', 's' => $p['status']]) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
<?php if ($canApprove && $st === 'eligible_for_review') : ?><div class="panel"><h2>Approve</h2><form method="post" action="<?= e($url) ?>" class="form-grid" data-confirm="Approve this commission?"><?= csrf_field() ?><input type="hidden" name="action" value="approve">
    <div class="field"><label for="apw">Your password</label><input id="apw" name="confirm_password" type="password" required autocomplete="current-password"></div><div class="form-actions"><button class="btn btn-primary" type="submit">Approve</button></div></form></div><?php endif; ?>
<?php if ($canApprove && in_array($st, ['pending_eligibility', 'eligible_for_review', 'approved', 'payable'], true)) : ?><div class="panel"><h2>Hold</h2><form method="post" action="<?= e($url) ?>" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="hold">
    <div class="field"><label for="hr">Reason (internal, required)</label><input id="hr" name="reason" required maxlength="255"></div><div class="field"><label for="hn">Note the partner may read (optional)</label><input id="hn" name="partner_note" maxlength="255"></div>
    <div class="form-actions"><button class="btn btn-ghost btn-sm" type="submit">Put on hold</button></div></form></div><?php endif; ?>
<?php if ($canApprove && $st === 'on_hold') : ?><div class="panel"><h2>Hold</h2><form method="post" action="<?= e($url) ?>" class="inline-form"><?= csrf_field() ?><input type="hidden" name="action" value="release"><button class="btn btn-primary btn-sm" type="submit">Release the hold</button></form></div><?php endif; ?>
<?php if ($canAdjust && !in_array($st, ['reversed'], true) && $e['milestone'] !== 'adjustment') : ?><div class="panel"><h2>Adjust or reverse</h2><p class="muted">The original entry and its calculation are never edited after approval: an adjustment adds a separate signed line.</p>
    <form method="post" action="<?= e($url) ?>" class="form-grid" data-confirm="Record this adjustment?"><?= csrf_field() ?><input type="hidden" name="action" value="adjust">
        <div class="field"><label for="ad">Direction</label><select id="ad" name="direction"><option value="decrease">Decrease</option><option value="increase">Increase</option></select></div>
        <div class="field"><label for="aa">Amount (₹)</label><input id="aa" name="amount" required inputmode="decimal"></div><div class="field"><label for="ar">Reason (required)</label><input id="ar" name="reason" required maxlength="255"></div>
        <div class="field"><label for="apw2">Your password</label><input id="apw2" name="confirm_password" type="password" required autocomplete="current-password"></div><div class="form-actions"><button class="btn btn-ghost btn-sm" type="submit">Add adjustment line</button></div></form>
    <form method="post" action="<?= e($url) ?>" class="form-grid" data-confirm="Reverse this commission?"><?= csrf_field() ?><input type="hidden" name="action" value="reverse">
        <div class="field"><label for="rr">Reversal reason (required)</label><input id="rr" name="reason" required maxlength="255"></div><div class="field"><label for="apw3">Your password</label><input id="apw3" name="confirm_password" type="password" required autocomplete="current-password"></div>
        <div class="form-actions"><button class="btn btn-danger btn-sm" type="submit">Reverse</button></div></form></div><?php endif; ?>
<?php if ($d['children'] !== []) : ?><div class="panel"><h2>Adjustment lines</h2><ul class="plain-list"><?php foreach ($d['children'] as $c) : ?><li><a href="/commissions/<?= e($c['public_id']) ?>"><?= e($c['reference']) ?></a> · <?= e(money($c['amount_minor'])) ?> · <?= View::partial('pbadge', ['kind' => 'commission', 's' => $c['status']]) ?> · <?= e($c['reason'] ?? '') ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<div class="panel"><h2>History</h2><ol class="timeline"><?php foreach ($d['history'] as $h) : ?><li><strong><?= e(ucfirst(str_replace('_', ' ', $h['event']))) ?></strong> <span class="muted"><?= e(local_time($h['created_at'])) ?> · <?= e($h['actor'] ?? 'system') ?></span>
    <?php if ($h['reason']) : ?><p class="prewrap"><?= e($h['reason']) ?></p><?php endif; ?><?php if ($h['before_json'] || $h['after_json']) : ?><p class="muted">Before: <?= e((string) ($h['before_json'] ?? '—')) ?><br>After: <?= e((string) ($h['after_json'] ?? '—')) ?></p><?php endif; ?></li><?php endforeach; ?></ol></div>
<div class="panel"><h2>Internal notes <span class="badge badge-sensitive">staff only</span></h2>
    <?php foreach ($d['notes'] as $n) : ?><div class="note"><p class="prewrap"><?= e($n['body']) ?></p><p class="muted"><?= e($n['author'] ?? '') ?> · <?= e(local_time($n['created_at'])) ?></p></div><?php endforeach; ?><?php if ($d['notes'] === []) : ?><p class="muted">No notes.</p><?php endif; ?>
    <form method="post" action="<?= e($url) ?>" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="note"><div class="field"><label for="nb">Add a note</label><textarea id="nb" name="body" rows="2" required maxlength="3000"></textarea></div><div class="form-actions"><button class="btn btn-ghost btn-sm" type="submit">Add note</button></div></form></div>
